const A=document.body.dataset.assetBase||'../assets/images/project-gallery/auditing-i/';
const figure=(file,alt,caption)=>`<figure class="tab-media-figure"><button class="media-magnify tab-media-frame" type="button" data-full="${A}${file}" data-alt="${alt}" data-caption="${caption}" aria-label="Enlarge image: ${alt}"><img loading="lazy" decoding="async" src="${A}${file}" alt="${alt}"><span aria-hidden="true"></span></button><figcaption>${caption}</figcaption></figure>`;

const chapters=[
  {id:'diagnose',label:'Diagnose',content:`<div class="chapter-body tab-editorial tab-text-led"><section class="editorial-text-section"><h3>A strong course with a clearer story to tell</h3><p>Linda’s original course already had a strong instructional foundation: current disciplinary content, measurable course-level objectives, practice questions, and thoughtfully selected technologies. The 2020 Quality Matters self-review scored it 50 out of 100, but many of the gaps involved making the design more visible—clearer orientation, one consistent set of outcomes, measurable module objectives, and explicit connections among materials, activities, and assessments. The review called for focused structural improvements, not a wholesale rescue.</p></section><section class="editorial-text-section"><h3>VR opened a larger design question</h3><p>The opportunity to add a virtual warehouse changed the scale of our thinking. Rather than bolt an impressive simulation onto an otherwise conventional sequence, we asked how the entire course could prepare students to gather evidence, document judgment, and communicate findings. The simulation became a reason to reconsider how textbook knowledge, practical activities, peer interaction, and assessment could build toward authentic performance.</p></section></div>`},
  {id:'align',label:'Align',content:`<div class="chapter-body tab-editorial"><section class="editorial-text-section"><h3>Building the course around visible alignment</h3><p>We consolidated the course-level outcomes, wrote measurable module objectives, and built a course map linking each objective to instructional materials, practice, summative assessment, and program goals. The redesigned map made six course outcomes and fourteen modules traceable rather than implicit.</p><div class="experience-grid"><article><h3>Orient learners</h3><p>A consistent home page and Getting Started structure clarified navigation, policies, communication, technology, and support.</p></article><article><h3>Make purpose explicit</h3><p>Module objectives and overview language showed why readings, lectures, practice, and assessments belonged together.</p></article><article><h3>Build a varied practice ecosystem</h3><p>Traditional textbook exercises and quizzes remained, but now sat alongside EarthWear cases, Tableau analysis, workpapers, practical activities, and the inventory-audit project.</p></article></div></section><section class="editorial-text-section"><h3>The star still needed a supporting cast</h3><p>The VR simulation was naturally the most visible feature, but it could not carry the course by itself. Cases, data visualization, analytical procedures, and documentation tasks gave students multiple ways to practice the component skills surrounding an audit. By the final module, physical inventory evidence gathering, workpaper preparation, and a client management letter were connected directly to outcomes for analysis and communication. The simulation was not a shiny detour; it was the culminating performance in a sequence designed to make it meaningful.</p></section></div>`},
  {id:'simulate',label:'Simulate',content:`<div class="chapter-body tab-editorial"><div class="editorial-pair image-right"><div><h3>A warehouse built for judgment</h3><p>In the VR experience, students entered a warehouse, located a randomized sample of inventory, opened boxes, evaluated quantities and conditions, and recorded observations in downloadable workpapers. The spatial environment made details consequential: a missing tag, damaged product, or absent box became evidence to interpret rather than a fact supplied in a textbook problem.</p></div>${figure('warehouse-aisles-1.jpg','Aisles of numbered inventory in the VR warehouse','Numbered aisles and shelf locations turned sampling into a spatial investigation.')}</div><section class="editorial-feature"><h3>A semester-long runway into VR</h3><p>Students did not encounter the complex audit on their first day in a headset. Earlier sessions helped them acclimate physically to VR, learn the controls, orient themselves inside the warehouse, complete simpler tasks, and interact with classmates through the collaborative environment. By the time they performed the full inventory audit, the technology itself required less attention—leaving more cognitive space for evidence gathering and professional judgment.</p></section><section class="editorial-feature"><h3>Designing in partnership</h3><p>Linda and I met regularly with Glimpse Group’s VR team—then Adept XR and now Foretell Reality—to define the experience, test successive builds, provide feedback, and plan future improvements. The partnership treated the simulation as an evolving instructional product rather than a one-time technical deliverable.</p><div class="editorial-inline-gallery">${figure('box-inspection.jpg','An open inventory box in the VR warehouse','Students opened selected boxes and compared their contents with inventory records.')}${figure('set-condition.jpg','The VR box-condition entry panel','The work interface translated observations into auditable conditions and notes.')}</div></section><section class="editorial-feature"><h3>Necessity became a second simulation</h3><p>A few months before launch, Linda learned that a student with a severe visual impairment would be taking the course. The planned desktop mode removed the headset, but it did not provide an accessible equivalent—and building one was outside the VR partner’s scope. Offering that learner a lesser assignment was technically possible. It was also unacceptable to me.</p><p>I built <a href="../work/kitchen-cordon-bleu.html">Kitchen Cordon Bleu</a> from scratch in Articulate Storyline, making every component screen-reader compatible while preserving the exploratory warehouse audit. Then, because I am apparently incapable of leaving well enough alone, I added a company backstory, characters, employee conversations, subplots, expanded inventory conditions, and complex logic systems. The result became a substantive simulation in its own right, and we offered it to the entire class; several students chose it instead of—or in addition to—the VR version.</p><p><a class="button" href="../work/kitchen-cordon-bleu.html">Explore the desktop simulation case study →</a></p></section></div>`},
  {id:'evidence',label:'Evidence',content:`<div class="chapter-body tab-editorial tab-text-led"><section class="editorial-text-section"><h3>Students connected the simulation to the profession</h3><p>Eighteen students responded to the inaugural implementation survey. On a five-point scale, they rated the simulation 4.3 for providing a realistic inventory-audit experience, 4.4 for helping them understand what auditors do, 4.3 for helping them feel prepared for a real audit, and 4.1 for providing experience that could help them stand out when applying for jobs.</p><div class="metric-grid"><div class="metric"><strong>4.4</strong><span>Understood what auditors do on the job</span></div><div class="metric"><strong>4.3</strong><span>Realistic, authentic audit experience</span></div><div class="metric"><strong>4.3</strong><span>Better prepared for a real inventory audit</span></div><div class="metric"><strong>4.1</strong><span>Career-relevant experience</span></div></div><div class="quote-grid"><blockquote>“There is no way simply reading about auditing procedures can entirely prepare you. Experience is a valuable teacher.”<cite>Student survey</cite></blockquote><blockquote>“I enjoyed being like a detective in the game and having a chance to try to do an audit without the tough consequences.”<cite>Student survey</cite></blockquote><blockquote>“Much better than just reading about it in a book.”<cite>Student survey</cite></blockquote></div></section><section class="editorial-text-section"><h3>Continuation became another form of evidence</h3><p>The VR simulation was not a one-semester pilot that disappeared after launch. Linda reported in 2024 that it was in its fourth year and had recently been licensed to another university—evidence that the initial investment grew into a durable instructional product.</p></section></div>`},
  {id:'iterate',label:'Iterate',content:`<div class="chapter-body tab-editorial"><section class="editorial-text-section"><h3>Feedback revealed where immersion helped—and where it got in the way</h3><p>VR respondents rated immersive virtual reality 4.0/5 for its impact on learning, and many praised the feeling of walking through a real audit. But the survey also surfaced motion sickness, performance problems, difficulty examining some boxes, and confusion around the “Call Supervisor” function. One student’s adverse physical response is an important reminder that immersion is not inherently inclusive.</p></section><div class="editorial-pair image-left">${figure('workpapers.jpg','Inventory workpapers inside the VR warehouse','Downloadable workpapers connected exploration with professional documentation.')}<div><h3>Parallel formats improved one another</h3><p>Students asked for clearer written preparation, smoother navigation, more box conditions, richer employee interaction, partner collaboration, and additional ways to investigate the warehouse. VR users rated interactive employees 4.5/5 in usefulness for a future version. Kitchen Cordon Bleu had already explored several of those ideas, and students specifically requested that aspects of it carry into the VR experience. Even if my Storyline version is no longer in use, its spirit continues through lessons and features applied to later VR iterations.</p></div></div><section class="editorial-text-section"><h3>When added realism becomes added noise</h3><p>Reviewing student feedback and assignment performance revealed a harder lesson. The narrative detail in Kitchen Cordon Bleu clearly created curiosity and engagement, but some learners became caught up in the story, misinterpreted information, or lost focus on the audit itself. I had solved the accessibility problem—and then, in my enthusiasm, created a new instructional problem. In a future revision, I would work with Linda to remove superfluous details and preserve only the narrative elements that sharpen the professional task.</p></section><section class="editorial-text-section"><h3>What I carried forward</h3><p>This project reinforced both why I build and why ambition needs editing. Accessibility should not mean offering a diminished experience; it can become the impetus for a richer solution that benefits everyone. But richness is not the same as accumulation. Novel technology, narrative detail, and creative flourishes earn their place only when they remain aligned to the performance learners are there to practice.</p><p><a href="https://ir.theglimpsegroup.com/adept-xr-partners-with-nova-southeastern-university-to-launch-vr-experiences-for-finance-and-accounting/">Read the 2021 Adept XR announcement ↗</a><br><a href="https://campustechnology.com/articles/2021/02/04/florida-university-turns-to-vr-to-teach-personal-finance.aspx">Read the Campus Technology coverage ↗</a><br><a href="https://nsuworks.nova.edu/lec_conference/2024/events/21/">Watch Linda Kidwell’s 2024 conference presentation ↗</a></p></section></div>`}
];

document.querySelector('#layout-root').innerHTML=`<div class="tab-list" role="tablist" aria-label="Case study chapters">${chapters.map((c,i)=>`<button role="tab" id="tab-${c.id}" aria-controls="tab-panel-${c.id}" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${c.label}</button>`).join('')}</div>${chapters.map((c,i)=>`<section class="card tab-panel" role="tabpanel" id="tab-panel-${c.id}" aria-labelledby="tab-${c.id}" ${i?'hidden':''}><div class="tab-panel-grid">${c.content}</div></section>`).join('')}`;

const tabs=[...document.querySelectorAll('[role="tab"]')];
function selectTab(tab){tabs.forEach(button=>{const active=button===tab;button.setAttribute('aria-selected',active);button.tabIndex=active?0:-1;document.querySelector(`#${button.getAttribute('aria-controls')}`).hidden=!active;});}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[next]);tabs[next].focus();});});

const dialog=document.createElement('dialog');dialog.className='image-lightbox';dialog.innerHTML='<div class="lightbox-inner"><button class="lightbox-close" type="button" aria-label="Close enlarged image">×</button><img alt=""><p></p></div>';document.body.append(dialog);
document.addEventListener('click',event=>{const button=event.target.closest('.media-magnify');if(!button)return;dialog.querySelector('img').src=button.dataset.full;dialog.querySelector('img').alt=button.dataset.alt;dialog.querySelector('p').textContent=button.dataset.caption;dialog.showModal();});
dialog.querySelector('.lightbox-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});
